cssProposal:
/* Asset 05 A1: static design overlay only, injected for mock-ups. */
#btns .ui150-label, #restL, #atkL, #mmn, #cr.c193 .rail button small {
 font-family:Itim,system-ui,sans-serif!important;font-weight:400!important;
 color:#FFF3DB!important;line-height:1.5!important;letter-spacing:0!important;
 -webkit-text-stroke:1.5px #1B1330;paint-order:stroke fill;
 text-shadow:0 1px 2px #1B1330;overflow:visible!important;
 white-space:nowrap;flex-shrink:0;
}
#btns .ui150-label {font-size:13px!important;max-width:46px;margin:0!important;}
#btns button, body.thumbs #btns button {width:56px;min-width:56px;height:56px;min-height:56px;padding:4px;gap:2px;}
#btns, body.thumbs #btns {gap:6px;}
#btns img.pxi,body.thumbs #btns img.pxi {width:24px;height:24px;}
#bRest #restL {font-size:13px!important;max-width:48px;margin-top:1px!important;}
#act #bRest,body.thumbs #act #bRest {width:56px!important;height:56px!important;font-size:21px!important;line-height:1!important;}
#hud #xpT {font:700 18px/1.35 system-ui,sans-serif!important;color:#FFF3DB!important;
 right:6px!important;top:0!important;max-width:calc(100% - 12px);white-space:nowrap;
 font-variant-numeric:tabular-nums;text-shadow:0 1px 2px #1B1330;
 -webkit-text-stroke:1.5px #1B1330;paint-order:stroke fill;}
#hud #xpw {height:26px!important;min-height:26px;margin-top:5px;}
body.thumbs.sys175 #lampBar {top:calc(130px + env(safe-area-inset-top,0px))!important;}
body.thumbs:not(.sys175) #lampBar {top:calc(116px + env(safe-area-inset-top,0px))!important;}
#cr.c193 .rail {gap:6px!important;}
#cr.c193 .rail button {width:56px!important;height:56px!important;min-width:56px!important;min-height:56px!important;flex-shrink:0;gap:1px;background:#2C213D!important;border-color:#BDA06A!important;color:#FFF3DB!important;opacity:1!important;}
#cr.c193 .rail button.on {background:#4B355F!important;border-color:#FFD27A!important;box-shadow:0 0 0 2px #FFD27A55,0 3px 8px #0007!important;}
#cr.c193 .rail button small {font-size:13px!important;max-width:48px!important;margin-top:0!important;}
#cr.c193 .rail button.dim small {color:#D5CBB7!important;}
#atkL {font-size:14px!important;max-width:70px!important;margin-top:2px;}
#mmn {font-size:13px!important;max-width:144px!important;width:144px;white-space:normal;overflow-wrap:break-word;text-align:center;}
#mmw {min-width:156px;gap:4px!important;}
@media (min-height:600px) {
 #btns .ui150-label,#bRest #restL,#cr.c193 .rail button small,#mmn {font-size:14px!important;}
 #btns button,body.thumbs #btns button {width:60px;min-width:60px;height:60px;min-height:60px;}
 #btns .ui150-label {max-width:50px;}
 #act #bRest,body.thumbs #act #bRest {width:60px!important;height:60px!important;}
 #cr.c193 .rail button {width:60px!important;height:60px!important;min-width:60px!important;min-height:60px!important;}
 #cr.c193 .rail button small {max-width:52px!important;}
 #hud #xpT {font-size:20px!important;}
 #hud #xpw {height:29px!important;min-height:29px;}
 #atkL {font-size:15px!important;}
}

cssProposalAdult:
/* Asset 05 A2 — adult labels. Static CSS; the child/creator A1 sheet stays separate. */
body:not(.kidmin171) #btns .ui150-label,
body:not(.kidmin171) #bRest #restL,
body:not(.kidmin171) #act #atkL,
body:not(.kidmin171) #act #skL,
body:not(.kidmin171) #act #bSlot2 small,
body:not(.kidmin171) #act #bSlot3 small,
body:not(.kidmin171) #act #bBuff small,
body:not(.kidmin171) #act #bPot small,
body:not(.kidmin171) #act #bQuest small,
body:not(.kidmin171) #act #bAuto small,
body:not(.kidmin171) #mmn {
 font-family:Itim,system-ui,sans-serif!important;font-size:12px!important;font-weight:700!important;
 color:#FFF3DB!important;line-height:1.5!important;text-shadow:0 1px 2px #1B1330,-1px 0 #1B1330,1px 0 #1B1330;
 -webkit-text-stroke:0.6px #1B1330;paint-order:stroke fill;white-space:nowrap;display:block;flex-shrink:0;
}
body:not(.kidmin171) #topR{top:calc(8px + env(safe-area-inset-top,0px))!important;right:calc(12px + env(safe-area-inset-right,0px))!important;gap:4px!important;}
body:not(.kidmin171) #btns{gap:4px!important;}
body:not(.kidmin171) #btns button{box-sizing:border-box;width:48px!important;min-width:48px!important;height:48px!important;min-height:48px!important;padding:2px!important;gap:0!important;}
body:not(.kidmin171) #btns img.pxi{width:22px!important;height:22px!important;}
body:not(.kidmin171) #btns .ui150-label{max-width:42px!important;margin:0!important;}
body:not(.kidmin171) #act #bRest{width:56px!important;height:56px!important;line-height:1!important;}
body:not(.kidmin171) #bRest #restL{max-width:48px!important;margin:0!important;}
body:not(.kidmin171) #hud #xpT{font:700 18px/1.35 system-ui,sans-serif!important;color:#FFF3DB!important;top:0!important;right:3px!important;text-shadow:0 1px 2px #1B1330;-webkit-text-stroke:1.5px #1B1330;paint-order:stroke fill;}
body:not(.kidmin171) #hud #xpw{height:26px!important;min-height:26px!important;margin-top:5px!important;}
body:not(.kidmin171).thumbs.sys175 #lampBar{top:calc(130px + env(safe-area-inset-top,0px))!important;}
body:not(.kidmin171).thumbs:not(.sys175) #lampBar{top:calc(116px + env(safe-area-inset-top,0px))!important;}
body:not(.kidmin171) #act #atkL{font-size:14px!important;margin-top:0!important;}
body:not(.kidmin171) #act #skL,
body:not(.kidmin171) #act #bSlot2 small,
body:not(.kidmin171) #act #bSlot3 small{max-width:56px!important;margin:0!important;}
body:not(.kidmin171) #act #bBuff small,
body:not(.kidmin171) #act #bPot small,
body:not(.kidmin171) #act #bQuest small,
body:not(.kidmin171) #act #bAuto small{max-width:44px!important;margin:0!important;}
body:not(.kidmin171) #act #bQuest,
body:not(.kidmin171) #act #bAuto{width:44px!important;height:44px!important;min-width:44px!important;min-height:44px!important;padding:0!important;gap:0!important;}
body:not(.kidmin171) #act #bQuest img.pxi,
body:not(.kidmin171) #act #bAuto img.pxi{width:20px!important;height:20px!important;}
/* A horizontal minimap card leaves space for guide → skill → attack even at 330 px high. */
body:not(.kidmin171) #mmw{box-sizing:border-box;display:grid!important;grid-template-columns:62px minmax(0,1fr);align-items:center;gap:4px!important;width:168px!important;min-width:168px!important;height:54px!important;padding:4px!important;}
body:not(.kidmin171) #mm{box-sizing:border-box;width:62px!important;height:42px!important;max-width:62px!important;max-height:42px!important;object-fit:contain;}
body:not(.kidmin171) #mmn{width:auto!important;max-width:none!important;white-space:normal!important;overflow-wrap:normal;line-height:1.5!important;text-align:center;}
/* Specificity also wins over the 2.13 g213 guide relocation. No per-frame layout writes. */
body:not(.kidmin171).thumbs.rov180 #act #bQuest{right:calc(12px + env(safe-area-inset-right,0px))!important;top:calc(118px + env(safe-area-inset-top,0px))!important;bottom:auto!important;}
body:not(.kidmin171).thumbs.rov180 #act #bAuto{right:calc(62px + env(safe-area-inset-right,0px))!important;top:calc(118px + env(safe-area-inset-top,0px))!important;bottom:auto!important;}
@media(max-height:350px){body:not(.kidmin171).thumbs.rov180 #act #bSk{bottom:calc(102px + env(safe-area-inset-bottom,0px))!important;}}
@media(min-height:600px){
 body:not(.kidmin171) #btns button{width:56px!important;min-width:56px!important;height:56px!important;min-height:56px!important;}
 body:not(.kidmin171) #btns .ui150-label,body:not(.kidmin171) #bRest #restL,body:not(.kidmin171) #mmn{font-size:14px!important;max-width:50px!important;}
 body:not(.kidmin171) #btns img.pxi{width:26px!important;height:26px!important;}
 body:not(.kidmin171) #hud #xpT{font-size:20px!important;}
 body:not(.kidmin171) #hud #xpw{height:29px!important;}
 body:not(.kidmin171) #mmw{display:flex!important;flex-direction:column;width:168px!important;height:142px!important;gap:4px!important;}
 body:not(.kidmin171) #mm{width:128px!important;height:86px!important;max-width:128px!important;max-height:86px!important;}
 body:not(.kidmin171) #mmn{width:154px!important;max-width:154px!important;}
 body:not(.kidmin171).thumbs.rov180 #act #bQuest,body:not(.kidmin171).thumbs.rov180 #act #bAuto{top:calc(214px + env(safe-area-inset-top,0px))!important;}
}

body:not(.kidmin171) #act #bPot img.pxi{width:22px!important;height:22px!important;}
/* Give the fallback Thai font room for เสริมพลัง without shrinking the text. */
body:not(.kidmin171) #act #bBuff small{max-width:48px!important;}
/* A child with kid mode switched off keeps the child's controls; clear the attack edge. */
body:not(.kidmin171).thumbs:not(.rov180) #act #bSlot2,
body:not(.kidmin171).thumbs:not(.rov180) #act #bJ1{right:calc(98px + env(safe-area-inset-right,0px))!important;}
